    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xB7915C741B0FF3D9ULL + 0xFBD25C4505C1659CULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xB81AB86079914DF9ULL + 0xECB797E50F4A57E7ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0x81A4A67B22BA22C9ULL + 0xC14C7118F8B55E67ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0xB879C04D20B267FFULL + 0xE97AB29E9747BDBDULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseC(pNonce * 0xD1948C5137B124A9ULL + 0xE108DB32BF3E6D35ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseC(pNonce * 0xF2E07D548A5397B1ULL + 0x9A5EDE3F9C291D4AULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0x9205106C4F50A71DULL + 0xB759F963CAC9BD05ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseB(pNonce * 0x9E51BE46913B661DULL + 0xCE6CCFCFF405FEE6ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseB(pNonce * 0xB4E63247C761AF6BULL + 0x9696C32F9D8CA625ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseC(pNonce * 0x92CBFAFEE0578B8DULL + 0x98178FC2EB4D9F7BULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseC(pNonce * 0xEE2136BDC9A3F903ULL + 0xF25F80C3FC620E18ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0x9FD6520776188E67ULL + 0x950F6D23B2BFF702ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseB(pNonce * 0xF0821CF8180A9549ULL + 0x87713931219120BBULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseB(pNonce * 0xBA437A4E87EEA3C5ULL + 0xE8C1B10EAE941DF9ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseA(pNonce * 0xE4E44AF43EDB5A41ULL + 0xF2B749C15AF01FFFULL);
