            aIngress ^= (RotL64(aLightningLaneB[((aIndex + 12867U)) & S_BLOCK1], 43U) ^ RotL64(aWaterLaneB[((aIndex + 10879U)) & S_BLOCK1], 5U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
