            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 12832U)) & S_BLOCK1], 29U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 14426U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 11746U)) & S_BLOCK1], 47U) ^ RotL64(aMagmaLaneC[((aIndex + 15179U)) & S_BLOCK1], 20U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
