            aWandererE = aWandererE + (((RotL64(aCross, 19U) + aOrbiterI) + RotL64(aOrbiterG, 29U)) + RotL64(aCarry, 21U));
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 41U) + RotL64(aOrbiterC, 37U)) + aOrbiterK);
            aWandererK = aWandererK + ((RotL64(aIngress, 43U) + aOrbiterH) + RotL64(aOrbiterC, 27U));
