            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0x90393C8BE1D64774ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x7D4767704763DCDFULL), 51U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0x41D6EC271D947D84ULL) + aKeyRotateAOrbiterUpdateSaltC[((aIndex + 29U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x64C987BEAB5F5945ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x0D87DA4CCC41F6EDULL), 37U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0xA21E1E7647BF2348ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x1D10DABA5F383B7BULL;
